package com.onlinelibrary.dao.impl;
import com.onlinelibrary.dao.NotificationDAO; import com.onlinelibrary.model.Notification; import com.onlinelibrary.util.DBConnection; import java.sql.*; import java.util.*;
public class NotificationDAOImpl implements NotificationDAO {
 private Notification map(ResultSet r)throws SQLException{Notification n=new Notification();n.setId(r.getLong("id"));n.setMemberId(r.getLong("member_id"));n.setTitle(r.getString("title"));n.setMessage(r.getString("message"));n.setType(r.getString("type"));n.setRead(r.getBoolean("is_read"));n.setCreatedAt(r.getTimestamp("created_at").toLocalDateTime());return n;}
 public List<Notification> findForMember(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM notifications WHERE member_id=? ORDER BY created_at DESC")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){List<Notification>x=new ArrayList<>();while(r.next())x.add(map(r));return x;}}}
 public long unreadCount(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM notifications WHERE member_id=? AND is_read=FALSE")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
 public void markRead(long member,long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET is_read=TRUE WHERE id=? AND member_id=?")){p.setLong(1,id);p.setLong(2,member);p.executeUpdate();}}
 public void create(long member,String title,String message,String type)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO notifications(member_id,title,message,type) VALUES(?,?,?,?)")){p.setLong(1,member);p.setString(2,title);p.setString(3,message);p.setString(4,type);p.executeUpdate();}}
 public void announce(Long member,String title,String message)throws SQLException{String q=member==null?"INSERT INTO notifications(member_id,title,message,type) SELECT id,?,?,'ANNOUNCEMENT' FROM users WHERE role='MEMBER' AND status='ACTIVE'":"INSERT INTO notifications(member_id,title,message,type) VALUES(?,?,?,'ANNOUNCEMENT')";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){if(member==null){p.setString(1,title);p.setString(2,message);}else{p.setLong(1,member);p.setString(2,title);p.setString(3,message);}p.executeUpdate();}}
 public void newArrival(String title)throws SQLException{String q="INSERT INTO notifications(member_id,title,message,type) SELECT u.id,?,CONCAT(?, ' is now available in the library.'),'NEW_ARRIVAL' FROM users u JOIN notification_preferences p ON p.member_id=u.id AND p.new_arrival_enabled=TRUE WHERE u.role='MEMBER' AND u.status='ACTIVE'";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,"New arrival: "+title);p.setString(2,title);p.executeUpdate();}}
}
